-- Run only as database owner. All Auth and classroom fixtures are rolled back.
begin;
create temporary table test_ids(k text primary key,id uuid default gen_random_uuid(),value text);
create temporary table test_results(title text,passed boolean);
grant select,insert,update on test_ids,test_results to authenticated,anon;
insert into test_ids(k) select unnest(array['teacher1','teacher2','student1','student2','student3','student4','student5','class1','class2','sectionA','sectionB','sectionC','otherSection']);
create function pg_temp.uid(k text) returns uuid language sql as $$ select id from pg_temp.test_ids where test_ids.k=$1 $$;
create function pg_temp.assume(k text) returns void language sql as $$ select set_config('request.jwt.claim.sub',pg_temp.uid(k)::text,true)::void $$;
create function pg_temp.ok(value boolean,title text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAILED: %',title;end if; insert into pg_temp.test_results values(title,true);end $$;
create function pg_temp.denied(statement text,title text,expected text default null) returns void language plpgsql as $$ declare rejected boolean:=false; message text;begin begin execute statement;exception when others then rejected:=true;message:=sqlerrm;end;perform pg_temp.ok(rejected and (expected is null or message ilike '%'||expected||'%'),title||coalesce(' ['||message||']',''));end $$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) select id,k||'@projectlens-test.invalid',now(),jsonb_build_object('name',k,'role','teacher') from test_ids where k like 'teacher%' or k like 'student%';
-- Exercise verified teacher activation inside this rollback-only transaction.
update auth.users set email_confirmed_at=now() where lower(email)='hassanabbas@tuf.edu.pk';
select pg_temp.ok((select r.role='teacher' from public.user_roles r join public.profiles p on p.id=r.id where lower(p.email)='hassanabbas@tuf.edu.pk'),'Verified allowlisted teacher claims the teacher role through the trusted Auth trigger');
select pg_temp.ok((select bool_and(role='student') from public.user_roles where id in (select id from test_ids where k like 'student%')),'Editable signup metadata cannot grant teacher roles');
update public.user_roles set role='teacher' where id in (select id from test_ids where k like 'teacher%');
insert into public.classes(id,teacher_id,title) values(pg_temp.uid('class1'),pg_temp.uid('teacher1'),'TEST class 1'),(pg_temp.uid('class2'),pg_temp.uid('teacher2'),'TEST class 2');
insert into public.sections(id,class_id,name) values(pg_temp.uid('sectionA'),pg_temp.uid('class1'),'A'),(pg_temp.uid('sectionB'),pg_temp.uid('class1'),'B'),(pg_temp.uid('sectionC'),pg_temp.uid('class1'),'C'),(pg_temp.uid('otherSection'),pg_temp.uid('class2'),'A');
insert into private.enrollment_codes(section_id,code) select id,'test-code-'||k from test_ids where k like 'section%';
set local role authenticated;
do $$ declare r jsonb; aid uuid; gid uuid; pid uuid; vid uuid; ev uuid; criterion uuid; class_value uuid:=pg_temp.uid('class1');begin
 perform pg_temp.assume('teacher1');
 r:=public.workspace_action('assignment_create',jsonb_build_object('class_id',class_value,'title','TEST assignment','description','Test brief','category','Messaging Application','technologies',jsonb_build_array('React'),'mode','both','min_group',2,'max_group',2,'proposal_required',true,'proposal_deadline',now()+interval '1 day','deadline',now()+interval '2 days','allow_late',false,'allow_resubmit',true,'sections',jsonb_build_array(jsonb_build_object('section_id',pg_temp.uid('sectionA')),jsonb_build_object('section_id',pg_temp.uid('sectionB')),jsonb_build_object('section_id',pg_temp.uid('sectionC'))),'requirements',jsonb_build_array('Authentication'),'rubric',jsonb_build_array(jsonb_build_object('title','Shared','max_marks',90,'individual',false),jsonb_build_object('title','Viva','max_marks',10,'individual',true))));
 aid:=(r->>'id')::uuid;insert into pg_temp.test_ids(k,id) values('assignment',aid);
 perform pg_temp.ok((select count(*)=3 from public.assignment_sections where assignment_id=aid),'Teacher creates assignment with sections A/B/C');
 r:=public.workspace_action('assignment_create',jsonb_build_object('class_id',class_value,'title','TEST A only','category','Portfolio','technologies','[]'::jsonb,'mode','both','min_group',2,'max_group',4,'proposal_required',false,'deadline',now()+interval '2 days','sections',jsonb_build_array(jsonb_build_object('section_id',pg_temp.uid('sectionA'))),'requirements','[]'::jsonb,'rubric',jsonb_build_array(jsonb_build_object('title','Shared','max_marks',100,'individual',false))));
 insert into pg_temp.test_ids(k,id) values('assignmentA',(r->>'id')::uuid);
 perform pg_temp.assume('teacher2');perform pg_temp.ok((select count(*)=0 from public.assignments where id=aid),'Unrelated teacher cannot read another class assignment');
 perform pg_temp.denied(format('select public.workspace_action(''enrollment_codes'',%L::jsonb)',jsonb_build_object('class_id',class_value)),'Unrelated teacher cannot access enrollment codes','Teacher access');
 perform pg_temp.assume('student1');perform public.workspace_action('enroll','{"code":"test-code-sectionA","roll_number":"ROLL-1"}');
 perform pg_temp.assume('student2');perform public.workspace_action('enroll','{"code":"test-code-sectionA","roll_number":"ROLL-2"}');
 perform pg_temp.assume('student3');perform public.workspace_action('enroll','{"code":"test-code-sectionB","roll_number":"ROLL-3"}');
 perform pg_temp.ok((select count(*)=0 from public.assignments where id=pg_temp.uid('assignmentA')),'Section B cannot read an A-only assignment');
 perform pg_temp.assume('student4');perform public.workspace_action('enroll','{"code":"test-code-sectionA","roll_number":"ROLL-4"}');
 perform pg_temp.assume('student5');perform public.workspace_action('enroll','{"code":"test-code-sectionA","roll_number":"ROLL-5"}');
 perform pg_temp.assume('student1');
 perform pg_temp.ok((select count(*)=2 from public.assignments where class_id=class_value),'Section A sees authorized assignments');
 perform pg_temp.denied('update public.user_roles set role=''teacher'' where id=auth.uid()','Student cannot promote their role','permission denied');
 perform pg_temp.denied('update public.enrollments set section_id=pg_temp.uid(''sectionB'') where student_id=auth.uid()','Student cannot freely change sections','permission denied');
 perform pg_temp.denied('select public.workspace_action(''enroll'',''{"code":"test-code-sectionB","roll_number":"OTHER"}'')','Existing enrollment cannot be replaced by another code','already enrolled');
 r:=public.workspace_action('group_create',jsonb_build_object('assignment_id',aid,'section_id',pg_temp.uid('sectionA'),'name','TEST team'));gid:=(r->>'id')::uuid;insert into pg_temp.test_ids(k,id) values('group',gid);
 perform pg_temp.denied(format('select public.workspace_action(''invite_member'',%L::jsonb)',jsonb_build_object('group_id',gid,'email','student3@projectlens-test.invalid')),'Cross-section group invitation denied','No eligible');
 perform public.workspace_action('invite_member',jsonb_build_object('group_id',gid,'email','student2@projectlens-test.invalid'));
 perform pg_temp.ok((select count(*)=1 from public.group_members where group_id=gid),'Invitations do not immediately create membership');
 perform pg_temp.assume('student2');perform pg_temp.ok((select count(*)=1 from public.group_invitations where group_id=gid),'Invitee can read invitation without recursive policies');
 perform public.workspace_action('respond_invite',jsonb_build_object('group_id',gid,'accept',true));
 perform pg_temp.ok((select count(*)=2 from public.group_members where group_id=gid),'Accepted invitation creates same-section membership');
 perform pg_temp.assume('student1');perform public.workspace_action('invite_member',jsonb_build_object('group_id',gid,'email','student4@projectlens-test.invalid'));
 perform pg_temp.assume('student4');perform pg_temp.denied(format('select public.workspace_action(''respond_invite'',%L::jsonb)',jsonb_build_object('group_id',gid,'accept',true)),'Group maximum is enforced on acceptance','size limit');
 perform pg_temp.assume('student2');perform pg_temp.denied(format('select public.workspace_action(''group_create'',%L::jsonb)',jsonb_build_object('assignment_id',aid,'section_id',pg_temp.uid('sectionA'),'name','Duplicate membership')),'Multiple group memberships for the same assignment are rejected','duplicate key');
 perform pg_temp.assume('student1');r:=public.workspace_action('project_create',jsonb_build_object('assignment_id',aid,'section_id',pg_temp.uid('sectionA'),'group_id',gid,'title','TEST project','description','Working project','technologies',jsonb_build_array('React')));pid:=(r->>'id')::uuid;insert into pg_temp.test_ids(k,id) values('project',pid);
 perform public.workspace_action('proposal_save',jsonb_build_object('project_id',pid,'body','TEST proposal','status','submitted'));
 perform pg_temp.assume('teacher1');perform public.workspace_action('proposal_decision',jsonb_build_object('project_id',pid,'status','approved'));
 perform pg_temp.assume('student1');r:=public.workspace_action('version_create',jsonb_build_object('project_id',pid));vid:=(r->>'id')::uuid;insert into pg_temp.test_ids(k,id) values('version',vid);
 perform pg_temp.assume('student2');perform pg_temp.denied(format('select public.workspace_action(''submit_version'',%L::jsonb)',jsonb_build_object('version_id',vid)),'Only leader can submit a group version','leader');
 perform pg_temp.assume('student3');perform pg_temp.ok((select count(*)=0 from public.projects where id=pid),'Unrelated section student cannot read private project');perform pg_temp.ok((select count(*)=0 from public.submission_versions where id=vid),'Unrelated student cannot read private source version');
 perform pg_temp.ok(not private.storage_visible(vid||'/source.zip'),'Unrelated student cannot access private Storage source');
 perform pg_temp.assume('teacher2');perform pg_temp.ok((select count(*)=0 from public.projects where id=pid),'Unrelated teacher cannot read private project');
 perform pg_temp.assume('student1');perform pg_temp.ok(private.storage_editable(vid||'/source.zip'),'Leader can upload draft source');perform pg_temp.ok(not private.storage_editable(vid||'/anything.zip'),'Upload paths restricted to draft source.zip');
end $$;
reset role;
-- Simulate trusted validated-archive completion, without executing uploaded code.
select public.begin_source(pg_temp.uid('version'),pg_temp.uid('student1'));
select pg_temp.denied('select public.begin_source(pg_temp.uid(''version''),pg_temp.uid(''student1''))','Parallel processing claims are rejected','already running');
set local role authenticated;
do $$ begin
 perform pg_temp.assume('student1');
 perform pg_temp.ok(not private.storage_editable(pg_temp.uid('version')||'/source.zip'),'Source cannot change while validation is running');
 perform pg_temp.denied('select public.complete_source(pg_temp.uid(''version''),''[]'',''[]'',0,0)','Students cannot fabricate source analysis findings','permission denied');
end $$;
reset role;
select public.complete_source(pg_temp.uid('version'),'[{"path":"src/App.tsx","storage_path":"test/source","kind":"source","size":20,"indexed":true}]','[]',1,0);
set local role authenticated;
do $$ declare vid uuid:=pg_temp.uid('version'); pid uuid:=pg_temp.uid('project'); aid uuid:=pg_temp.uid('assignment'); r jsonb; ev uuid; criterion uuid;begin
 perform pg_temp.assume('student1');perform public.workspace_action('submit_version',jsonb_build_object('version_id',vid));
 perform pg_temp.ok((select status='submitted' and submitted_at is not null from public.submission_versions where id=vid),'Leader submits a version using server time');
 perform pg_temp.ok((select count(*)=2 from public.submission_members where version_id=vid),'Submitted version preserves membership snapshot');
 perform pg_temp.ok(not private.storage_editable(vid||'/source.zip'),'Submitted source cannot be overwritten in Storage');
 perform pg_temp.denied('update public.submission_versions set snapshot=''{}'' where id=pg_temp.uid(''version'')','Submitted snapshot cannot be silently overwritten','permission denied');
 perform pg_temp.denied(format('select public.workspace_action(''review_transition'',%L::jsonb)',jsonb_build_object('version_id',vid,'status','approved')),'Student cannot approve submission','Teacher access');
 perform pg_temp.assume('teacher1');perform public.workspace_action('review_transition',jsonb_build_object('version_id',vid,'status','under_review'));
 select id into criterion from public.rubric_criteria where assignment_id=aid and not individual;
 perform pg_temp.denied(format('select public.workspace_action(''evaluation_save'',%L::jsonb)',jsonb_build_object('version_id',vid,'scores',jsonb_build_array(jsonb_build_object('criterion_id',criterion,'marks',91)))),'Marks cannot exceed criterion maximum','Marks must match');
 perform public.workspace_action('evaluation_save',jsonb_build_object('version_id',vid,'strengths','TEST strength','comments','Draft private comment','scores',jsonb_build_array(jsonb_build_object('criterion_id',criterion,'marks',80))));
 select id into ev from public.evaluations where version_id=vid;
 insert into pg_temp.test_ids(k,id) values('evaluation',ev);
 perform public.workspace_action('individual_save',jsonb_build_object('version_id',vid,'student_id',pg_temp.uid('student1'),'marks',8,'reason','TEST viva 1','private_feedback','PRIVATE ONE'));
 perform public.workspace_action('individual_save',jsonb_build_object('version_id',vid,'student_id',pg_temp.uid('student2'),'marks',9,'reason','TEST viva 2','private_feedback','PRIVATE TWO'));
 perform public.workspace_action('comment_add',jsonb_build_object('version_id',vid,'body','Private inline comment','path','src/App.tsx','line',1));
 perform pg_temp.ok((select version_id=vid from public.evaluations where id=ev),'Evaluation references the exact version reviewed');
 perform pg_temp.assume('student1');perform pg_temp.ok((select count(*)=0 from public.evaluations where id=ev),'Draft evaluations remain private before release');perform pg_temp.ok((select count(*)=0 from public.evaluation_scores where evaluation_id=ev),'Draft scores remain private before release');perform pg_temp.ok((select count(*)=0 from public.individual_results where evaluation_id=ev),'Draft individual feedback remains private');perform pg_temp.ok((select count(*)=0 from public.review_comments where version_id=vid),'Draft inline comments remain private');
 perform pg_temp.denied('insert into public.evaluation_scores(evaluation_id,criterion_id,marks) select pg_temp.uid(''evaluation''),id,100 from public.rubric_criteria limit 1','Student cannot write marks directly','permission denied');
 perform pg_temp.assume('teacher1');perform public.workspace_action('review_transition',jsonb_build_object('version_id',vid,'status','approved'));perform public.workspace_action('release_results',jsonb_build_object('version_id',vid));
 perform pg_temp.assume('student1');perform pg_temp.ok((select count(*)=1 from public.evaluations where id=ev),'Explicit release exposes authorized shared evaluation');perform pg_temp.ok((select count(*)=1 from public.individual_results where evaluation_id=ev),'Student sees only their own individual result');perform pg_temp.ok((select private_feedback='PRIVATE ONE' from public.individual_results where evaluation_id=ev),'Student cannot read another member private feedback');perform pg_temp.ok((select count(*)=1 from public.review_comments where version_id=vid),'Released file-and-line feedback is visible');
 perform pg_temp.ok((select bool_and(user_id=auth.uid()) from public.notifications),'Notifications contain only the current user events');
 perform pg_temp.denied('insert into public.audit_events(class_id,action) values(pg_temp.uid(''class1''),''FAKE'')','Clients cannot fabricate audit events','permission denied');
 perform pg_temp.assume('student3');perform pg_temp.ok((select count(*)=0 from public.evaluations where id=ev),'Released results stay private from unrelated students');perform pg_temp.ok((select count(*)=0 from public.evaluation_scores where evaluation_id=ev),'Search and export source rows obey authorization');
 perform pg_temp.assume('teacher2');perform pg_temp.ok((select count(*)=0 from public.audit_events where class_id=pg_temp.uid('class1')),'Unrelated teacher cannot inspect classroom audit');
 perform pg_temp.assume('teacher1');perform pg_temp.ok((select count(*)=1 from public.projects where section_id=pg_temp.uid('sectionA') and id=pid),'Teacher Section A filter returns the right project');perform pg_temp.ok((select count(*)=0 from public.projects where section_id=pg_temp.uid('sectionB') and id=pid),'Teacher Section B filter excludes Section A project');
 perform public.workspace_action('review_transition',jsonb_build_object('version_id',vid,'status','under_review','reason','Recheck requested'));
 perform public.workspace_action('review_transition',jsonb_build_object('version_id',vid,'status','changes_requested','reason','Add documentation'));
 perform pg_temp.assume('student1');r:=public.workspace_action('version_create',jsonb_build_object('project_id',pid));perform pg_temp.ok((r->>'id')::uuid<>vid,'Revision request creates a new immutable version');
 perform pg_temp.assume('teacher1');perform pg_temp.ok((select count(*)>=4 from public.audit_events where version_id=vid and action like 'Evaluation record %'),'Grade values and changes are captured in audit history');
end $$;
reset role;
select public.complete_source((select id from public.submission_versions where project_id=pg_temp.uid('project') and version=2),'[]','[]',0,0);
update public.assignment_sections set deadline=now()-interval '1 minute' where assignment_id=pg_temp.uid('assignment') and section_id=pg_temp.uid('sectionA');
set local role authenticated;
do $$ begin
 perform pg_temp.assume('student1');
 perform pg_temp.denied(format('select public.workspace_action(''submit_version'',%L::jsonb)',jsonb_build_object('version_id',(select id from public.submission_versions where project_id=pg_temp.uid('project') and version=2))),'Section-specific deadline enforced on backend','deadline has passed');
 perform pg_temp.assume('teacher1');
 perform public.workspace_action('correct_enrollment',jsonb_build_object('id',(select id from public.enrollments where student_id=pg_temp.uid('student5') and ended_at is null),'section_id',pg_temp.uid('sectionC'),'reason','Teacher correction'));
 perform pg_temp.ok((select count(*)=2 from public.enrollments where student_id=pg_temp.uid('student5')),'Enrollment corrections preserve historical enrollment');
 perform pg_temp.denied(format('select public.workspace_action(''correct_enrollment'',%L::jsonb)',jsonb_build_object('id',(select id from public.enrollments where student_id=pg_temp.uid('student4') and ended_at is null),'section_id',pg_temp.uid('sectionA'),'roll_number','ROLL-5','reason','Attempt to reuse another student historical roll')),'Historical roll numbers cannot be reassigned to other students','already belongs');
end $$;
reset role;
select jsonb_build_object('passed',count(*),'checks',jsonb_agg(title order by title),'fixtures','All Auth, enrollment, project, and evaluation fixtures roll back') as authorization_results from test_results;
rollback;
